}

groups.command:
$dns = @('1.1.1.1','1.0.0.1')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$dns = @('8.8.8.8','8.8.4.4')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$dns = @('9.9.9.9','149.112.112.112')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$dns = @('94.140.14.14','94.140.15.15')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$ErrorActionPreference = 'Continue'
$store = 'HKCU:\System\GameConfigStore'
New-Item -Path $store -Force -ErrorAction SilentlyContinue | Out-Null
$values = @{ GameDVR_DXGIHonorFSEWindowsCompatible = 1 GameDVR_FSEBehavior = 2 GameDVR_FSEBehaviorMode = 2 GameDVR_HonorUserFSEBehaviorMode = 1
}
$held = 0
foreach ($name in $values.Keys) { try { New-ItemProperty -Path $store -Name $name -Value $values[$name] -PropertyType DWord -Force -ErrorAction Stop | Out-Null } catch { $held++ }
}
if ($held -gt 0) { Write-Host "$held fullscreen value(s) are held by Windows on this PC - the rest are in place." }
Write-Host 'Fullscreen optimisations set to exclusive mode.'

groups.revert:
$ErrorActionPreference = 'Continue'
$store = 'HKCU:\System\GameConfigStore'
$values = @{ GameDVR_DXGIHonorFSEWindowsCompatible = 0; GameDVR_FSEBehavior = 0; GameDVR_FSEBehaviorMode = 0; GameDVR_HonorUserFSEBehaviorMode = 0 }
foreach ($name in $values.Keys) { try { New-ItemProperty -Path $store -Name $name -Value $values[$name] -PropertyType DWord -Force -ErrorAction Stop | Out-Null } catch { Write-Host "$name stays as Windows left it." }
}
Write-Host 'Fullscreen optimisations back to the Windows default.'

groups.command:
powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 | Out-Null
$scheme = (powercfg /list | Select-String 'Ultimate Performance' | Select-Object -First 1)
if ($scheme -match '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})') { powercfg /setactive $Matches[1]; Write-Host 'Ultimate Performance activated.' }
else { powercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c; Write-Host 'Fell back to High Performance.' }

$svc = @('Fax','RemoteRegistry','RetailDemo','MapsBroker','WalletService','PhoneSvc','MessagingService', 'DiagTrack','dmwappushservice','diagnosticshub.standardcollector.service','DPS','WdiServiceHost','WdiSystemHost', 'lfsvc','SharedAccess','WerSvc','PcaSvc','TabletInputService','SCardSvr','SEMgrSvc','SysMain','WpcMonSvc')
foreach ($s in $svc) { if (Get-Service -Name $s -ErrorAction SilentlyContinue) { Set-Service -Name $s -StartupType Manual -ErrorAction SilentlyContinue Write-Host (' ' + $s + ' -> Manual') } }
Write-Host 'Service trim complete.'

$k = 'HKLM:\SOFTWARE\Policies\Microsoft\Edge'
New-Item -Path $k -Force | Out-Null
$vals = @{ MetricsReportingEnabled=0; SendSiteInfoToImproveServices=0; PersonalizationReportingEnabled=0; EdgeShoppingAssistantEnabled=0; ShowMicrosoftRewards=0; StartupBoostEnabled=0; BackgroundModeEnabled=0; UserFeedbackAllowed=0; DiagnosticData=0; EdgeCollectionsEnabled=0; HubsSidebarEnabled=0 }
foreach ($n in $vals.Keys) { New-ItemProperty -Path $k -Name $n -Value $vals[$n] -PropertyType DWord -Force | Out-Null }

New-Item -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Force -ErrorAction SilentlyContinue | Out-Null
'{f874310e-b6b7-47dc-bc84-b9e6b38f5903}','{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}' | ForEach-Object { $k = 'HKCU:\Software\Classes\CLSID\' + $_ New-Item -Path $k -Force | Out-Null New-ItemProperty -Path $k -Name 'System.IsPinnedToNameSpaceTree' -Value 0 -PropertyType DWord -Force | Out-Null }
New-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name LaunchTo -Value 1 -PropertyType DWord -Force | Out-Null

$ids = '{0DB7E03F-FC29-4DC6-9020-FF41B59E513A}','{3DFDF296-DBEC-4FB4-81D1-6A3438BCF4DE}','{A0953C92-50DC-43BF-BE83-3742FED03C9C}'
foreach ($id in $ids) { Remove-Item ('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\MyComputer\NameSpace\' + $id) -Recurse -Force -ErrorAction SilentlyContinue Remove-Item ('HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Explorer\MyComputer\NameSpace\' + $id) -Recurse -Force -ErrorAction SilentlyContinue }
Write-Host 'Legacy user folders removed from This PC.'

$p = Join-Path ([Environment]::GetFolderPath('Desktop')) 'God Mode.{ED7BA470-8E54-465E-825C-99712043E01C}'
if (-not (Test-Path $p)) { New-Item -Path $p -ItemType Directory | Out-Null }
Write-Host 'God Mode folder created on the desktop.'

Stop-Process -Name OneDrive -Force -ErrorAction SilentlyContinue
$setup = if (Test-Path "$env:SystemRoot\SysWOW64\OneDriveSetup.exe") { "$env:SystemRoot\SysWOW64\OneDriveSetup.exe" } else { "$env:SystemRoot\System32\OneDriveSetup.exe" }
if (Test-Path $setup) { Start-Process $setup -ArgumentList '/uninstall' -Wait -ErrorAction SilentlyContinue }
Remove-Item 'HKCU:\Software\Classes\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}' -Recurse -Force -ErrorAction SilentlyContinue
Write-Host 'OneDrive removed.'
